/* v8 additional hand-curated scenarios. Each record has localized teaching content,
   a safe command that runs in the lesson sandbox, and common operational pitfalls. */
'use strict';
const V8_MODULES = [
    ['b-perms', 'bash', ['الصلاحيات والعمل الآمن', 'Permissions et sécurité', 'Permissions and safe work'], ['افهم الأذونات والنسخ الآمن دون تعديل ملفات جهازك.', 'Comprendre les droits et les copies sûres.', 'Understand permissions and careful file operations.']],
    ['b-triage', 'bash', ['تحليل السجلات والبيانات', 'Analyse des journaux et des données', 'Log and data investigation'], ['تحويل السجلات إلى دلائل قابلة للتحقق.', 'Transformer les journaux en indices vérifiables.', 'Turn log records into verifiable evidence.']],
    ['b-netops', 'bash', ['مختبر شبكات Linux', 'Laboratoire réseau Linux', 'Linux network lab'], ['تشخيص الشبكة الافتراضية دون استعمال الإنترنت.', 'Diagnostiquer un réseau fictif hors ligne.', 'Diagnose a fully offline simulated network.']],
    ['b-reliable', 'bash', ['مهارات أوامر متينة', 'Commandes fiables', 'Reliable command workflows'], ['أنجز عمليات واضحة قابلة للتكرار والتحقق.', 'Effectuer des opérations vérifiables.', 'Build repeatable commands with predictable results.']],
    ['p-adminops', 'powershell', ['تشخيص وإدارة Windows', 'Diagnostic et administration Windows', 'Windows administration and diagnostics'], ['اقرأ حالة Windows الافتراضية وتحكم في أخطاء العمل.', 'Lire un Windows virtuel et gérer les erreurs.', 'Inspect synthetic Windows data and handle failures.']],
    ['p-netops', 'powershell', ['مختبر شبكات PowerShell', 'Laboratoire réseau PowerShell', 'PowerShell network lab'], ['تتبع IP وDNS وTCP وجدار الحماية بأوامر PowerShell.', 'Diagnostiquer IP, DNS, TCP et pare-feu.', 'Trace IP, DNS, TCP and firewall behavior.']],
    ['p-reporting', 'powershell', ['تحليل الكائنات والتقارير', 'Objets et rapports', 'Object pipelines and reporting'], ['ابن تقارير من كائنات وملفات بيانات افتراضية.', 'Construire des rapports sur des données fictives.', 'Create reports from virtual objects and files.']],
    ['p-reliability', 'powershell', ['التحقق واستكشاف الأخطاء', 'Validation et dépannage', 'Validation and troubleshooting'], ['تعلم التشخيص قبل أي تغيير في النظام.', 'Diagnostiquer avant chaque modification.', 'Diagnose issues before making changes.']]
];
for (const [id, shell, name, intro] of V8_MODULES) LESSON_MODULES.push({ id, shell, name: LT(...name), intro: LT(...intro) });
function L8(module, title, concept, explain, pitfall, syntax, lab, refs) {
    const titleLoc = LT(...title), conceptLoc = LT(...concept), explainLoc = LT(...explain), pitfallLoc = LT(...pitfall);
    const goal = LT('تعلّم تطبيق: ' + title[0] + ' على بيانات المختبر بأمان.', 'Savoir appliquer : ' + title[1] + ' sur des données de labo.', 'Practice ' + title[2].toLowerCase() + ' safely with lab data.');
    add(module, titleLoc, goal, conceptLoc, syntax, lab, explainLoc, pitfallLoc, lab, refs);
}
// Bash permissions: permissions are educational metadata, not host OS permission checks.
L8('b-perms', ['التمييز بين قراءة وكتابة وتنفيذ', 'Lire, écrire, exécuter', 'Read, write, execute'], ['r تسمح بالقراءة وw بالكتابة وx بالتنفيذ أو دخول المجلد. هذه بتات مستقلة لكل من المالك والمجموعة والآخرين.', 'r lit, w écrit, x exécute ou traverse un dossier. Chaque catégorie a ses propres bits.', 'r permits reading, w writing, and x execution or directory traversal. Owner, group and others each have their own bits.'], ['في 640 يحصل المالك على rw، والمجموعة على r، والآخرون على لا شيء.', 'En 640, le propriétaire a rw, le groupe r, les autres aucun droit.', 'Mode 640 means owner read/write, group read, everyone else no rights.'], ['المحاكي يخزن قيم chmod فقط؛ لا يمنع الوصول وفق هذه القيم.', 'Le simulateur stocke le mode, mais ne l’applique pas.', 'The simulator records permission metadata but does not enforce it.'], 'chmod 640 FILE', 'chmod 640 notes.txt', ['chmod', 'stat']);
L8('b-perms', ['التأكد من المسار قبل تغيير الأذونات', 'Vérifier un chemin avant chmod', 'Verify paths before chmod'], ['ابدأ بـpwd وls قبل أي تعديل. المسار النسبي يعتمد على المجلد الحالي، وقد يشير إلى ملف مختلف بعد cd.', 'Commencez par pwd et ls. Un chemin relatif dépend du dossier courant.', 'Start with pwd and ls: a relative path changes meaning when the working directory changes.'], ['عرض المسار أولاً يقلل أخطاء تعديل الملف الخطأ.', 'La vérification réduit le risque de modifier le mauvais fichier.', 'Inspecting the path first reduces accidental changes to the wrong file.'], ['لا تفترض أن notes.txt في كل مجلد هو الملف نفسه.', 'Un même nom peut désigner des fichiers différents.', 'An identical filename can refer to different files in different directories.'], 'pwd; ls; chmod 600 notes.txt', 'pwd; ls; chmod 600 notes.txt', ['pwd', 'ls', 'chmod']);
L8('b-perms', ['حماية النسخة الأصلية قبل التجربة', 'Conserver un original avant l’essai', 'Keep an original before testing'], ['قبل حذف أو تعديل المحتوى، انسخ الملف إلى مكان مستقل وتحقق من النسختين. لا تعوّل على إمكانية التراجع في بيئة حقيقية.', 'Copiez le fichier avant modification puis vérifiez les deux versions.', 'Copy a file before editing, then verify both files. A real system may not support undo.'], ['cp ينشئ نسخة منفصلة؛ cat يسمح بمراجعة المحتوى.', 'cp crée une copie et cat permet de la relire.', 'cp makes a separate copy and cat lets you verify its contents.'], ['نسخ ملف فوق نسخة احتياطية موجودة قد يمحوها.', 'Écraser une sauvegarde peut supprimer l’ancienne version.', 'Overwriting an existing backup can destroy your only known-good copy.'], 'cp notes.txt notes-backup.txt; cat notes-backup.txt', 'cp notes.txt notes-backup.txt; cat notes-backup.txt', ['cp', 'cat']);
L8('b-perms', ['مراجعة حجم البيانات قبل النسخ', 'Mesurer avant de copier', 'Measure before copying'], ['افحص حجم الملف أو المجلد لتقدير وقت النسخ ومساحة التخزين المطلوبة. du يحسب الحجم ضمن البيئة الافتراضية.', 'Vérifiez la taille avant toute copie; du affiche l’espace estimé.', 'Estimate storage requirements before copying. du computes a virtual size for the selected path.'], ['du -h يعرض وحدة أقرب للقراءة البشرية.', 'du -h affiche une unité plus lisible.', 'The -h flag provides a human-readable size.'], ['حجم المحاكي ليس حجم القرص الحقيقي ولا يعكس الملفات المتفرقة.', 'La taille du labo ne reflète pas le disque réel.', 'Lab sizes do not represent your actual disk usage.'], 'du -h logs', 'du -h logs', ['du', 'df']);
L8('b-perms', ['التأكد من سلامة النسخ بالبصمة', 'Vérifier une copie par empreinte', 'Verify copies by digest'], ['احسب SHA-256 للملف الأصلي والنسخة لتكتشف اختلاف المحتوى. التشابه لا يضمن هوية المصدر ولكنه اختبار سلامة مفيد.', 'Calculez SHA-256 sur la source et la copie pour comparer leur intégrité.', 'Compute SHA-256 for both the original and copy to check that content is identical.'], ['نسخ متطابقة تعطي نفس البصمة.', 'Des fichiers identiques donnent la même empreinte.', 'Identical content produces identical digests.'], ['البصمة ليست توقيعاً رقمياً ولا تثبت صاحب الملف.', 'Une empreinte ne prouve pas l’auteur.', 'A hash alone does not establish who authored a file.'], 'sha256sum notes.txt; cp notes.txt notes-copy.txt; sha256sum notes-copy.txt', 'sha256sum notes.txt; cp notes.txt notes-copy.txt; sha256sum notes-copy.txt', ['sha256sum', 'cp']);
L8('b-perms', ['البحث قبل حذف ملف', 'Trouver avant de supprimer', 'Find before deleting'], ['استعمل find لتحديد الملفات المطابقة قبل rm. تفادى حذف عدة ملفات اعتماداً على نمط لم تراجعه.', 'Listez d’abord les fichiers avec find avant toute suppression.', 'Find matching files first, and verify the resulting list before deleting anything.'], ['find يعرض النتائج دون تعديل الملفات.', 'find liste sans modifier les fichiers.', 'find is a read-only inventory step.'], ['rm -r قادر على حذف شجرة كاملة في نظام حقيقي؛ راجع الاسم بدقة.', 'rm -r peut effacer une arborescence entière.', 'A careless rm -r on a real machine can remove an entire directory tree.'], 'find logs -type f', 'find logs -type f', ['find', 'rm']);
// Bash data investigations
L8('b-triage', ['إنشاء تقرير للأخطاء فقط', 'Créer un rapport des erreurs', 'Produce an error-only report'], ['استعمل grep لاستخراج أسطر ERROR من ملف سجل ثم وجه المخرجات إلى تقرير منفصل. لا تحذف المصدر.', 'Utilisez grep puis une redirection pour extraire les lignes ERROR sans toucher à l’original.', 'Filter ERROR lines into a separate report with grep and redirection; preserve the original log.'], ['الرمز > ينشئ التقرير أو يستبدله، لا يعدل سجل المصدر.', '> crée ou remplace le rapport, sans changer le journal source.', 'The > operator creates or replaces the report, not the input log.'], ['استعمال > على اسم السجل الأصلي قد يفرغه قبل قراءته.', 'Évitez de rediriger vers le fichier source.', 'Never redirect output to the same source log; it can truncate that file.'], 'grep ERROR logs/app.log > errors.txt', 'grep ERROR logs/app.log > errors.txt', ['grep', 'cat']);
L8('b-triage', ['البحث دون حساسية لحالة الأحرف', 'Recherche sans casse', 'Case-insensitive log search'], ['قد يكتب البرنامج error أو ERROR أو Error. الخيار -i يطابق هذه الأشكال دون تغيير الملف.', 'Les journaux utilisent parfois error ou ERROR; -i ignore la casse.', 'Logs may use error or ERROR; grep -i searches without case sensitivity.'], ['اجمع مع -n لتظهر أرقام الأسطر عند الحاجة.', 'Ajoutez -n pour connaître les numéros de ligne.', 'Add -n if you need line numbers to locate matching records.'], ['البحث عن كلمة عامة مثل error قد يطابق سياقات غير مهمة.', 'Un motif trop vague peut correspondre à trop de lignes.', 'A broad term may match unrelated records.'], 'grep -i error logs/app.log', 'grep -i error logs/app.log', ['grep', 'rg']);
L8('b-triage', ['تمييز الملفات التي تحتوي أخطاء', 'Repérer les fichiers avec erreurs', 'Find error-bearing files'], ['عند وجود عدة سجلات استعمل rg للبحث بشكل متكرر داخل الشجرة، ثم راجع اسم الملف ورقم السطر.', 'rg peut parcourir un dossier et afficher fichier et numéro de ligne.', 'rg can recursively search a folder and include filename and line context.'], ['خزّن النتيجة في تقرير ليسهل مقارنتها لاحقاً.', 'Enregistrez les résultats pour faciliter la comparaison.', 'Save results to a report for later comparison.'], ['القائمة الخالية قد تعني غياب التطابق لا نجاح الخدمة.', 'Aucune correspondance ne prouve pas que le service fonctionne.', 'No match does not necessarily mean a healthy service.'], 'rg -n ERROR logs', 'rg -n ERROR logs', ['rg', 'grep']);
L8('b-triage', ['تحليل ملف JSON دون تخمين', 'Interroger JSON avec jq', 'Query JSON deliberately'], ['JSON يحتفظ بالبنية والأنواع. استعمل jq لاستخراج خاصية بدلاً من حذف الأقواس باستعمال تعابير عشوائية.', 'JSON garde une structure; jq extrait un champ sans casser le format.', 'JSON is structured data. Use jq to select a field rather than scraping the text with ad hoc string replacement.'], ['المحدد .name يقرأ خاصية name من كائن.', 'Le filtre .name lit une propriété du document.', 'The .name selector reads one property of a JSON object.'], ['المحاكي يدعم محددات jq البسيطة فقط؛ لا يشغّل برامج jq كاملة.', 'Le labo ne gère que des sélecteurs jq limités.', 'This simulator supports a small jq selector subset, not full jq programming.'], "jq -r '.name' data/config.json", "jq -r '.name' data/config.json", ['jq', 'cat']);
L8('b-triage', ['اكتشاف الصفوف المتكررة', 'Détecter les lignes répétées', 'Detect duplicate rows'], ['sort يرتب الأسطر ثم uniq يزيل المتجاور المكرر. لذلك شغّل sort أولاً للحصول على قيم فريدة صحيحة.', 'sort trie avant uniq, qui supprime uniquement les doublons adjacents.', 'uniq only collapses adjacent duplicates. Sorting first groups identical lines together.'], ['احتفظ بالنسخة الأصلية للمراجعة أو لإعادة الحساب.', 'Gardez les données originales pour l’audit.', 'Keep the original data available for audit and reprocessing.'], ['uniq وحده لا يضمن إزالة كل المكرر إذا لم تكن الأسطر متجاورة.', 'uniq seul peut laisser des doublons non adjacents.', 'uniq by itself may miss duplicates scattered through the input.'], 'cat names.txt | sort | uniq', 'cat names.txt | sort | uniq', ['sort', 'uniq', 'cat']);
L8('b-triage', ['عدّ الحوادث في سجل', 'Compter des événements dans un journal', 'Count log incidents'], ['يمكن إرسال نتيجة grep إلى wc -l لحساب الأسطر المطابقة، بدل تقدير عدد الحوادث بصرياً.', 'Transmettez les lignes filtrées à wc -l pour obtenir le nombre d’événements.', 'Pipe filtered log lines into wc -l to count matches rather than eyeballing a long log.'], ['عدد الأسطر يعتمد على دقة نمط البحث؛ راجع بعض التطابقات قبل الاعتماد عليه.', 'Le compte dépend du motif; vérifiez quelques correspondances.', 'Counts depend on the filter, so validate a few matches first.'], ['رسالة واحدة قد تمتد على أكثر من سطر في بعض التطبيقات.', 'Un incident peut occuper plusieurs lignes.', 'A single incident may span multiple lines in some logging formats.'], 'grep ERROR logs/app.log | wc -l', 'grep ERROR logs/app.log | wc -l', ['grep', 'wc']);
// Linux virtual network
L8('b-netops', ['قراءة واجهة وعنوان IP', 'Lire les adresses réseau', 'Inspect interface addressing'], ['عنوان IP والبادئة يحددان الشبكة المحلية. ip addr يعرض واجهات افتراضية في المختبر، وليس إعدادات الجهاز.', 'ip addr affiche une interface et son préfixe fictifs, pas ceux de votre PC.', 'ip addr lists synthetic interfaces and prefix lengths, never the device’s actual network settings.'], ['inet هو عنوان IPv4 والرقم بعد / هو طول البادئة.', 'inet donne IPv4 et /24 la longueur du préfixe.', 'inet shows an IPv4 address and /24 is its prefix length.'], ['تغيّر عنوان الشبكة الحقيقي يمكن أن يفصل جهازك عن الشبكة.', 'Changer une vraie IP peut couper la connexion.', 'Changing real IP settings can disconnect a machine.'], 'ip addr', 'ip addr', ['ip', 'ifconfig']);
L8('b-netops', ['قراءة المسار الافتراضي', 'Lire la route par défaut', 'Understand the default route'], ['Default Route يختار البوابة لحركة المرور خارج الشبكة المحلية. وجود مسار لا يضمن أن Gateway تستجيب.', 'La route par défaut indique une passerelle; sa présence ne garantit pas son accès.', 'The default route points to a gateway, but the gateway must still be reachable.'], ['في المختبر استعمل سيناريو Gateway down وقارن المخرجات.', 'Comparez le résultat avec le scénario « passerelle coupée ».', 'Compare the output after choosing the gateway-down scenario.'], ['لا تحذف Default Route الحقيقية أثناء التعلم.', 'Ne supprimez pas la route par défaut réelle.', 'Do not delete the default route on a real connected system.'], 'ip route', 'ip route', ['ip', 'route']);
L8('b-netops', ['اختبار الوصول إلى البوابة', 'Tester la passerelle', 'Ping the gateway'], ['ping يختبر استجابة ICMP. الفشل قد ينتج عن فصل الواجهة أو المسار أو تصفية ICMP؛ ليس دليلاً وحيداً.', 'ping teste ICMP; un échec peut venir du lien, du routage ou du filtrage.', 'ping tests ICMP reachability; failure may reflect link, route or filtering issues.'], ['نجاح ping لا يثبت أن HTTP يعمل.', 'Un ping réussi ne valide pas HTTP.', 'A successful ping does not prove HTTP is available.'], ['لا تفسر كل timeout على أنه خادم متوقف.', 'Un timeout ne prouve pas que le serveur est arrêté.', 'Not every timeout indicates a down server.'], 'ping -c 2 192.0.2.1', 'ping -c 2 192.0.2.1', ['ping']);
L8('b-netops', ['تمييز DNS عن مشكلة اتصال', 'Différencier DNS et connectivité', 'Separate DNS from connectivity'], ['DNS يترجم الاسم إلى عنوان. جرّب dig أولاً ثم ping للبوابة؛ فشل الأول مع نجاح الثاني يشير إلى مسار تشخيص مختلف.', 'Si dig échoue mais ping vers la passerelle réussit, cherchez côté DNS.', 'If DNS lookup fails but the gateway responds, focus on name resolution rather than the physical link.'], ['عنوان التدريب ثابت داخل السيناريو ولكن حالة الخادم قابلة للتغيير.', 'Le réseau virtuel a un nom de démonstration fixe.', 'The sandbox has a fixed training hostname but selectable fault states.'], ['لا تستخدم نتيجة DNS وحدها لتأكيد أن TCP يعمل.', 'DNS seul ne valide pas une connexion TCP.', 'Successful DNS does not imply TCP service availability.'], 'dig training.lab', 'dig training.lab', ['dig', 'nslookup']);
L8('b-netops', ['قراءة حالة منافذ TCP', 'Lire les ports TCP', 'Read TCP listening state'], ['ss -tuln يعرض المنافذ المستمعة. قد تكون الخدمة متوقفة رغم أن DNS والبوابة يعملان.', 'ss -tuln liste les sockets d’écoute; le service peut être arrêté malgré un DNS sain.', 'ss -tuln lists listening sockets. A service may be down even when the route and DNS are healthy.'], ['راجع عنوان الخدمة والمنفذ 443 الافتراضي.', 'Vérifiez l’adresse et le port virtuel 443.', 'Inspect the synthetic endpoint and TCP port 443.'], ['وجود Listen محلياً لا يثبت إمكانية الوصول عبر جدار الحماية.', 'Listen ne garantit pas l’accès distant.', 'A listening socket alone does not prove firewall reachability.'], 'ss -tuln', 'ss -tuln', ['ss', 'netstat']);
L8('b-netops', ['اختبار استجابة HTTP', 'Tester la réponse HTTP', 'Check HTTP response status'], ['curl -I يطلب عادة الرؤوس. هنا يقدم المختبر استجابة وهمية تتغير مع الخدمة والجدار وDNS، دون اتصال خارجي.', 'curl -I simule des en-têtes HTTP selon l’état DNS, serveur et pare-feu.', 'curl -I produces offline, scenario-dependent HTTP headers. No real request is sent.'], ['الرمز 200 يشير إلى نجاح HTTP في سيناريو المحاكاة.', '200 signifie une réponse HTTP réussie dans le scénario.', 'An HTTP 200 status means simulated web request success.'], ['لا تخلط بين محاكاة HTTP والوصول إلى موقع حقيقي.', 'Il ne s’agit d’aucune connexion Internet réelle.', 'This is not a real web request.'], 'curl -I https://training.lab', 'curl -I https://training.lab', ['curl']);
// Bash robust workflows
L8('b-reliable', ['تحقق من مكان العمل قبل الإنشاء', 'Vérifier le dossier courant', 'Check current location first'], ['الأمر pwd نقطة البداية لأي سلسلة تعدّل ملفات. بعد cd، يتغير معنى notes.txt، لذلك افحص مكانك قبل الكتابة.', 'pwd confirme le dossier de travail avant toute opération sur fichier.', 'pwd verifies your working directory before running commands that create or overwrite files.'], ['اجعل فحص المسار عادة قبل استخدام إعادة التوجيه.', 'Contrôlez le chemin avant > ou >>.', 'Check your path before redirection.'], ['الكتابة باسم نسبي من مجلد غير مقصود قد تفقد التقرير.', 'Un chemin relatif peut enregistrer au mauvais endroit.', 'A relative path can silently write somewhere unexpected.'], 'pwd; ls', 'pwd; ls', ['pwd', 'ls']);
L8('b-reliable', ['الفرق بين استبدال وإلحاق', 'Écraser ou ajouter', 'Overwrite versus append'], ['> يستبدل المحتوى القديم و>> يلحق نصاً جديداً. اختر أداة تناسب ما إذا كان الملف تقريراً جديداً أو سجلاً تراكمياً.', '> remplace; >> ajoute. Choisissez selon le type de rapport.', 'Use > to replace output, >> to append. Decide whether the report should accumulate records.'], ['اعرض الملف بعد الكتابة لتتحقق من النتيجة.', 'Relisez le fichier après écriture.', 'Read the file back to verify the expected content.'], ['لا تختبر > على بيانات لا تملك نسخة احتياطية منها.', 'N’écrasez jamais une source sans sauvegarde.', 'Do not overwrite valuable original files without backups.'], 'echo first > training.txt; echo second >> training.txt; cat training.txt', 'echo first > training.txt; echo second >> training.txt; cat training.txt', ['echo', 'cat']);
L8('b-reliable', ['التوقف عند فشل خطوة', 'Arrêter une chaîne en cas d’échec', 'Gate later steps on success'], ['&& ينفذ الأمر التالي فقط إذا نجح السابق. هذا مفيد لمنع تقرير مكتمل ظاهرياً عند فشل تجهيز البيانات.', '&& exécute la suite seulement après un succès.', 'The && operator only runs a following command if the preceding one succeeded.'], ['لا تحتاج إلى تنفيذ سلسلة كاملة لمعرفة أن خطوة فشلت.', 'La chaîne s’arrête à la première erreur.', 'The chain short-circuits after a failing step.'], ['تعامل مع فشل أوامر الفحص بوصفه حالة منطقية، وليس دوماً عطباً.', 'Certains tests échoués représentent une condition normale.', 'Some check commands intentionally return a nonzero status.'], 'mkdir -p training && echo ready > training/state.txt', 'mkdir -p training && echo ready > training/state.txt', ['mkdir', 'echo']);
L8('b-reliable', ['إنشاء تقارير قابلة للمراجعة', 'Créer des rapports auditables', 'Produce auditable reports'], ['احفظ نتائج الفلترة في ملف منفصل ثم اقرأه. افصل مصدر البيانات عن النتائج لتتمكن من إعادة التحليل.', 'Sauvegardez le résultat filtré sans écraser le journal de départ.', 'Save filtered results separately from your source data so the analysis can be reproduced.'], ['استعمل grep ثم redirection ثم cat للتحقق.', 'Chaînez grep, redirection et cat pour valider.', 'Filter, redirect and inspect the resulting report.'], ['لا تعتمد على نتيجة محفوظة قديمة إذا تغيّر المصدر.', 'Un rapport ancien peut ne plus représenter les données actuelles.', 'A saved report can go stale when the source log changes.'], 'grep ERROR logs/app.log > report.txt; cat report.txt', 'grep ERROR logs/app.log > report.txt; cat report.txt', ['grep', 'cat']);
L8('b-reliable', ['عزل متغيرات الجلسة', 'Isoler les variables de session', 'Keep session variables scoped'], ['المتغيرات تخزن نصوصاً مؤقتة داخل الجلسة، وexport يجعل متغير البيئة متاحاً للعمليات التابعة في Shell حقيقي.', 'export transmet une variable aux processus enfants sur un vrai shell.', 'export sets an environment variable for child processes in a real shell.'], ['اطبع قيمة المتغير للتأكد من تهجئة اسمه.', 'Affichez la valeur pour vérifier le nom.', 'Echo the variable to confirm its spelling and expansion.'], ['لا تحفظ أسراراً في أوامر يتم تسجيلها بتاريخ الأوامر.', 'Évitez les mots de passe dans l’historique.', 'Do not type passwords or tokens directly into command history.'], 'export TEAM=network; echo "$TEAM"', 'export TEAM=network; echo "$TEAM"', ['export', 'echo']);
L8('b-reliable', ['استعمال المساعدة كجزء من العمل', 'Lire l’aide avant action', 'Use help before changes'], ['لا تعتمد على حفظ المعاملات؛ اقرأ help أو man للنسخة المتاحة. صفحة المساعدة في هذا المختبر موجز تعليمي محدود.', 'Consultez man ou help; la documentation locale du labo est abrégée.', 'Check help or man instead of guessing flags. The in-lab manual is a curated summary only.'], ['تبدأ المساعدة باسم الأمر، ثم تراجع الصيغة قبل التجربة.', 'Demandez l’aide de la commande précise.', 'Request documentation for the exact command before trying parameters.'], ['لا تتوقع أن جميع خيارات man الحقيقية مدعومة في المختبر.', 'Le laboratoire ne reproduit pas toutes les pages man.', 'The lab does not include full real-world man pages.'], 'man ip', 'man ip', ['man', 'ip']);
// PowerShell administration and diagnosis
L8('p-adminops', ['عرض العمليات وتحديد الهوية', 'Lister et identifier les processus', 'Identify running processes'], ['Get-Process يعيد كائنات تملك Name وId وCPU؛ يمكنك تمريرها مباشرة لأوامر التصفية دون تحليل جدول نصي.', 'Get-Process retourne des objets avec Name, Id et CPU.', 'Get-Process produces objects with Name, Id, and CPU properties instead of flat text.'], ['استعمل Select-Object لتقليل الأعمدة بدل قص النص.', 'Select-Object sélectionne les propriétés utiles.', 'Select-Object chooses properties directly.'], ['هذه عمليات وهمية في المختبر ولا تعكس برامج جهازك.', 'Ces processus sont fictifs.', 'These process records are synthetic.'], 'Get-Process | Select-Object -Property Name,Id', 'Get-Process | Select-Object -Property Name,Id', ['Get-Process', 'Select-Object']);
L8('p-adminops', ['تصفية العمليات حسب الاستهلاك', 'Filtrer les processus par CPU', 'Filter processes by CPU'], ['Where-Object يقارن خصائص كائنات PowerShell. استعمل -Property و-gt لتحديد العمليات التي تجاوزت قيمة.', 'Where-Object compare des propriétés avec -gt.', 'Where-Object evaluates object properties with operators such as -gt.'], ['يتم الفحص قبل تنسيق الجدول، للحفاظ على الكائنات.', 'Filtrez avant Format-Table pour garder les objets.', 'Filter objects before formatting them to preserve structure.'], ['CPU هنا قيم تدريبية ثابتة وليست عينات أداء حقيقية.', 'Le CPU affiché est simulé.', 'CPU values in the lab are sample numbers, not live measurements.'], 'Get-Process | Where-Object -Property CPU -gt 1', 'Get-Process | Where-Object -Property CPU -gt 1', ['Get-Process', 'Where-Object']);
L8('p-adminops', ['حالة الخدمات قبل محاولة الإصلاح', 'Inspecter les services avant correction', 'Inspect service status first'], ['Get-Service يوفر Name وStatus للخدمات. ابدأ بالقراءة: الخدمة المتوقفة ليست دائماً عطباً، فقد تكون معطلة عمداً.', 'Get-Service affiche Name et Status; un service arrêté peut être normal.', 'Get-Service shows service name and status. A stopped service is not always a fault.'], ['قارن الحالات المختلفة قبل التفكير في Start-Service على نظام حقيقي.', 'Comparez les états avant de modifier les services.', 'Review statuses before modifying a real service.'], ['المختبر لا يشغّل أو يوقف أي خدمة على Windows.', 'Le labo ne modifie aucun service réel.', 'The simulator never starts or stops host services.'], 'Get-Service | Where-Object -Property Status -eq Running', 'Get-Service | Where-Object -Property Status -eq Running', ['Get-Service', 'Where-Object']);
L8('p-adminops', ['تحقق من سلامة ملف', 'Contrôler l’intégrité d’un fichier', 'Check file integrity'], ['Get-FileHash يحسب SHA-256 داخل المختبر. قارن بصمات المصدر والنسخة لتعرف هل تغير المحتوى.', 'Get-FileHash calcule SHA-256 pour comparer deux contenus.', 'Get-FileHash computes SHA-256 over virtual file content; matching hashes indicate matching bytes.'], ['اختيار Hash يتيح حفظ البصمة دون باقي الأعمدة.', 'Sélectionnez Hash pour produire un rapport.', 'Select the Hash property for a compact integrity report.'], ['SHA-256 يثبت تطابق محتوى الملف، ولا يثبت الثقة في مصدره.', 'Le hash ne prouve pas la provenance.', 'A hash verifies content equality, not trust in the source.'], 'Get-FileHash notes.txt | Select-Object -Property Hash', 'Get-FileHash notes.txt | Select-Object -Property Hash', ['Get-FileHash', 'Select-Object']);
L8('p-adminops', ['قراءة صلاحيات تعليمية', 'Lire les permissions pédagogiques', 'Read educational permission metadata'], ['Get-Acl في Windows الحقيقي يعرض قوائم صلاحيات معقدة. هنا يوفر المختبر mode مبسطاً ولا ينفّذ قواعد أمنية.', 'Le vrai Get-Acl lit des ACL Windows. Le labo n’expose qu’un mode simplifié.', 'Real Get-Acl inspects Windows ACLs. In the lab only simplified permission metadata is shown.'], ['افرق بين قراءة المعلومات وتغيير صلاحيات جهازك الحقيقي.', 'Distinguez lecture de métadonnées et modification réelle.', 'Distinguish a sample record from actual host access control.'], ['لا تستعمل 644 كبديل عن دراسة ACE وACL في Windows.', 'Le mode 644 ne remplace pas une ACL Windows.', 'Unix-style 644 is not a substitute for Windows ACL semantics.'], 'Get-Acl notes.txt', 'Get-Acl notes.txt', ['Get-Acl']);
L8('p-adminops', ['جمع عدد العمليات في تقرير', 'Compter les processus', 'Count processes in a report'], ['Measure-Object يجمع إحصاءات على الكائنات القادمة من pipeline. هو أداة تحليل، وليس أمراً لعرض كامل خصائص العملية.', 'Measure-Object produit des statistiques sur les objets du pipeline.', 'Measure-Object aggregates pipeline items. Use it for counts and measurements, not process details.'], ['شغّل Get-Process أولاً ثم Measure-Object على النتائج.', 'Comptez les objets produits par Get-Process.', 'Count the objects emitted by Get-Process.'], ['عداد المحاكي يمثل عمليات وهمية محدودة فقط.', 'Le compte du labo porte sur un échantillon fictif.', 'The lab count only covers its small synthetic process dataset.'], 'Get-Process | Measure-Object', 'Get-Process | Measure-Object', ['Measure-Object', 'Get-Process']);
// PowerShell virtual network
L8('p-netops', ['التمييز بين IPv4 والواجهة', 'IPv4 et interface réseau', 'IPv4 and interface identity'], ['Get-NetIPAddress يعرض IPAddress وPrefixLength وInterfaceAlias. استعمل هذه الخصائص لتحديد الواجهة قبل الانتقال إلى أي تشخيص.', 'Get-NetIPAddress affiche l’adresse, le préfixe et le nom d’interface.', 'Get-NetIPAddress provides IPAddress, PrefixLength, and InterfaceAlias, a baseline for network troubleshooting.'], ['عنوان TEST-NET-1 المعروض للتدريب فقط، وليس عنوان جهازك.', 'L’adresse d’exemple est réservée à la documentation.', 'The TEST-NET address is documentation-only, not your real machine address.'], ['لا تنسخ عنوان المحاكاة لتثبيت IP على جهاز حقيقي.', 'Ne configurez pas cette IP fictive sur votre ordinateur.', 'Never use the sandbox address as real network configuration.'], 'Get-NetIPAddress', 'Get-NetIPAddress', ['Get-NetIPAddress']);
L8('p-netops', ['تحديد مسار الخروج', 'Identifier la route de sortie', 'Identify outbound routing'], ['Get-NetRoute يعرض DestinationPrefix وNextHop. Default Route هو المسار المعتاد للوجهات خارج الشبكة المحلية.', 'Get-NetRoute affiche le préfixe et le prochain saut.', 'Get-NetRoute shows the destination prefix and next hop used to forward traffic.'], ['قارن نتيجة المختبر بعد اختيار عطل Gateway.', 'Comparez le résultat après panne de passerelle.', 'Try the broken-gateway scene and inspect the route state.'], ['وجود route في الجدول لا يضمن أن البوابة قابلة للوصول.', 'Une route présente peut rester inutilisable.', 'A configured route does not guarantee a working gateway.'], 'Get-NetRoute', 'Get-NetRoute', ['Get-NetRoute']);
L8('p-netops', ['تحديد خادم DNS', 'Trouver le serveur DNS', 'Find configured DNS'], ['Get-DnsClientServerAddress يبين خادم DNS الذي تستعمله الواجهة. وجود عنوان للخادم لا يضمن أن الخدمة ترد.', 'Get-DnsClientServerAddress affiche un serveur DNS configuré, sans garantie de réponse.', 'Get-DnsClientServerAddress shows the configured resolver. Configuration alone does not prove availability.'], ['بعد قراءة العنوان تحقق فعلياً من حل اسم عبر Resolve-DnsName.', 'Vérifiez la résolution avec Resolve-DnsName.', 'Follow up with Resolve-DnsName to test DNS behavior.'], ['تغيير DNS الحقيقي قد يؤثر على الوصول لخدمات الشبكة.', 'Modifier le vrai DNS peut perturber vos accès.', 'Changing real DNS settings can disrupt connectivity.'], 'Get-DnsClientServerAddress', 'Get-DnsClientServerAddress', ['Get-DnsClientServerAddress']);
L8('p-netops', ['اختبار حل اسم محلي', 'Tester la résolution d’un nom', 'Resolve a training hostname'], ['Resolve-DnsName يفصل مشكلة اسم المضيف عن مشكلة Port TCP. في المختبر يتأثر بإعداد DNS والبوابة والواجهة.', 'Resolve-DnsName distingue la résolution d’un test de port TCP.', 'Resolve-DnsName tests name resolution separately from TCP. The lab responds based on virtual network state.'], ['اسم training.lab يحل افتراضياً إلى TEST-NET-2 فقط في المختبر.', 'training.lab renvoie une adresse de documentation dans le labo.', 'training.lab resolves to a documentation address in the sandbox.'], ['نجاح DNS لا يعني أن خادم الويب يشغّل HTTPS.', 'La résolution DNS ne garantit pas HTTPS.', 'Successful DNS does not guarantee a healthy HTTPS endpoint.'], 'Resolve-DnsName training.lab', 'Resolve-DnsName training.lab', ['Resolve-DnsName']);
L8('p-netops', ['التأكد من الوصول عبر ICMP', 'Tester ICMP indépendamment', 'Test independent ICMP reachability'], ['Test-Connection أداة لاختبار ICMP، وهي مختلفة عن فحص TCP. ابدأ بالبوابة إذا فشل الوصول لخدمة بعيدة.', 'Test-Connection teste ICMP et pas un port TCP.', 'Test-Connection checks ICMP, not application ports. Test the gateway first when routing may be broken.'], ['قارن Test-Connection بالاختبار على Port 443.', 'Comparez ICMP avec un test du port 443.', 'Compare this result against Test-NetConnection with port 443.'], ['قد يمنع Firewall حزم ICMP رغم عمل TCP بشكل طبيعي.', 'Le filtrage peut bloquer ICMP alors que TCP fonctionne.', 'ICMP may be blocked even when TCP still works in a real network.'], 'Test-Connection 192.0.2.1', 'Test-Connection 192.0.2.1', ['Test-Connection']);
L8('p-netops', ['اختبار خدمة HTTPS ومنفذ 443', 'Tester HTTPS sur le port 443', 'Test HTTPS port 443'], ['Test-NetConnection -Port يفحص مدى الوصول إلى منفذ TCP. المختبر يحسب النجاح وفق حالة DNS والبوابة والخادم والجدار الناري.', 'Test-NetConnection -Port dépend des états DNS, passerelle, serveur et pare-feu fictifs.', 'Test-NetConnection -Port assesses synthetic TCP reachability based on gateway, DNS, server and firewall toggles.'], ['افحص TcpTestSucceeded، وليس حالة ICMP فقط.', 'Regardez TcpTestSucceeded plutôt que le ping seul.', 'Read TcpTestSucceeded, not just the ping indicator.'], ['نجاح TCP لا يثبت صحة محتوى التطبيق أو شهادة TLS.', 'Le succès TCP ne valide pas le contenu applicatif ni TLS.', 'TCP success does not validate application content or TLS certificates.'], 'Test-NetConnection training.lab -Port 443', 'Test-NetConnection training.lab -Port 443', ['Test-NetConnection']);
// PowerShell object reporting
L8('p-reporting', ['اختيار خصائص كائن دون فقد النوع', 'Choisir des propriétés sans casser les objets', 'Select object properties'], ['Select-Object يرجع كائنات تحتوي الخصائص المحددة. هذا يختلف عن Format-Table الذي يعد مخرجات للعرض.', 'Select-Object conserve des objets avec un choix de propriétés.', 'Select-Object projects selected properties into new objects. Format-Table is primarily for display.'], ['يمكن الاستمرار في pipeline بعد Select-Object لأن النتيجة بنيوية.', 'On peut poursuivre le pipeline avec des objets structurés.', 'You can continue processing selected properties in the pipeline.'], ['لا تستخدم Format-Table قبل Export-Csv إذا كنت تحتاج بيانات سليمة.', 'Évitez Format-Table avant Export-Csv.', 'Do not format objects before exporting structured data.'], 'Get-Process | Select-Object -Property Name,Id', 'Get-Process | Select-Object -Property Name,Id', ['Select-Object', 'Get-Process']);
L8('p-reporting', ['التصفية بمعاملات المقارنة', 'Filtrer avec les comparateurs', 'Filter with comparison operators'], ['Where-Object -Property Status -eq Running يختار الكائنات التي يساوي حقل Status فيها القيمة.', 'Where-Object compare une propriété à une valeur donnée.', 'Where-Object tests a specific object property using an operator such as -eq.'], ['اكتب اسم الخاصية الصحيح قبل مقارنة قيمها.', 'Contrôlez le nom de propriété avant le filtre.', 'Inspect property names before filtering.'], ['قيم النصوص قد تختلف بين الأدوات والإصدارات؛ اقرأ البيانات أولاً.', 'Les valeurs peuvent varier selon l’outil.', 'Property values may vary between tool versions and systems.'], 'Get-Service | Where-Object -Property Status -eq Running', 'Get-Service | Where-Object -Property Status -eq Running', ['Where-Object', 'Get-Service']);
L8('p-reporting', ['تقسيم البيانات إلى مجموعات', 'Regrouper par propriété', 'Group records by property'], ['Group-Object يجمع الكائنات بحسب قيمة خاصية، مثل Status. يفيد لفهم توزيع الحالات بدلاً من سرد كل عنصر.', 'Group-Object regroupe des objets selon la même valeur de propriété.', 'Group-Object groups objects sharing a property value and summarizes their counts.'], ['يمكن فحص الخدمات Running وStopped كمجموعتين.', 'Regroupez les services par état.', 'Group sample services by status.'], ['لا تتوقع أن ترتيب المجموعات ثابت على كل نسخة من PowerShell.', 'Ne supposez pas un ordre de groupes garanti.', 'Do not rely on group ordering across environments.'], 'Get-Service | Group-Object Status', 'Get-Service | Group-Object Status', ['Group-Object', 'Get-Service']);
L8('p-reporting', ['استيراد CSV ككائنات', 'Importer CSV sous forme d’objets', 'Import CSV as objects'], ['Import-Csv يحوّل رأس الأعمدة إلى أسماء خصائص. تأكد من سلامة الفواصل وعلامات الاقتباس قبل التصفية.', 'Import-Csv utilise l’en-tête comme noms de propriétés.', 'Import-Csv uses the header row as property names. Check delimiters and quoting before analysis.'], ['صف واحد في CSV يصبح كائناً مستقلاً.', 'Chaque ligne devient un objet distinct.', 'Each data row becomes an object with named fields.'], ['وجود فاصلة داخل حقل مقتبس يحتاج محلل CSV صحيح.', 'Une virgule dans un champ cité nécessite un parseur CSV.', 'Quoted fields can contain commas; avoid splitting CSV on commas manually.'], 'Import-Csv data/users.csv', 'Import-Csv data/users.csv', ['Import-Csv']);
L8('p-reporting', ['تحويل JSON إلى خصائص', 'Transformer JSON en objets', 'Parse JSON to properties'], ['ConvertFrom-Json يفك JSON إلى كائنات يمكن اختيار خصائصها. تحقق من صحة JSON قبل الاعتماد عليه.', 'ConvertFrom-Json produit des objets utilisables dans le pipeline.', 'ConvertFrom-Json parses structured text into objects with addressable properties.'], ['يبدأ المثال بقراءة ملف ثم تفكيك JSON دون تعديل المصدر.', 'L’exemple lit puis interprète le document sans modification.', 'The example reads and parses without modifying the input.'], ['لا تستخدم Replace على الأقواس لتحليل JSON في سكربت موثوق.', 'Évitez les substitutions textuelles pour analyser JSON.', 'Do not attempt to parse JSON by stripping punctuation.'], 'Get-Content data/config.json | ConvertFrom-Json', 'Get-Content data/config.json | ConvertFrom-Json', ['ConvertFrom-Json', 'Get-Content']);
L8('p-reporting', ['حفظ تقرير بصيغة نصية', 'Enregistrer un rapport texte', 'Save a text report'], ['Out-File يحفظ العرض النصي للنتيجة. إذا أردت إعادة استعمال الخصائص كبيانات فاستخدم Export-Csv أو ConvertTo-Json.', 'Out-File écrit du texte; Export-Csv ou JSON conserve mieux la structure.', 'Out-File saves text. Choose structured export when downstream tools require properties and types.'], ['أعد قراءة التقرير بعد الحفظ للتحقق من محتواه.', 'Relisez le fichier exporté pour validation.', 'Read the file back to check its contents.'], ['نص الجداول قد يختصر قيم الخصائص الطويلة.', 'Le format texte peut tronquer certaines valeurs.', 'Formatted tables can truncate lengthy values.'], 'Get-Service | Select-Object -Property Name,Status | Out-File services.txt', 'Get-Service | Select-Object -Property Name,Status | Out-File services.txt', ['Out-File', 'Get-Service']);
// PowerShell troubleshooting practice
L8('p-reliability', ['ابحث عن المساعدة قبل تغيير الإعدادات', 'Lire l’aide avant modification', 'Read help before making changes'], ['Get-Help يوضح المعاملات والأمثلة الخاصة بأمر PowerShell. داخل المختبر المساعدة ملخص تعليمي لا نسخة من ملفات الجهاز.', 'Get-Help indique des paramètres et exemples; la version labo est abrégée.', 'Get-Help describes parameters and examples. The lab serves curated help, not your system’s installed help.'], ['اقرأ Syntax ثم انتقل لمثال يقلل المخاطرة.', 'Commencez par la syntaxe et un exemple en lecture seule.', 'Start with syntax and a read-only example.'], ['معاملات Cmdlet قد تختلف بين Windows PowerShell وPowerShell 7.', 'Les paramètres varient selon la version.', 'Available parameters may differ by PowerShell version and platform.'], 'Get-Help Get-NetRoute', 'Get-Help Get-NetRoute', ['Get-Help', 'Get-NetRoute']);
L8('p-reliability', ['التحقق من وجود مسار', 'Valider un chemin', 'Check a path before using it'], ['Test-Path يرجع True أو False بدلاً من رمي خطأ على كل ملف مفقود. استعمله قبل القراءة أو النسخ.', 'Test-Path retourne un booléen au lieu d’une erreur pour une absence normale.', 'Test-Path returns a Boolean and is useful before reads, copies and destructive changes.'], ['في المختبر أسماء الملفات ومساراتها افتراضية.', 'Les chemins du laboratoire sont fictifs.', 'Every path here belongs to the virtual filesystem.'], ['عدم وجود ملف ليس دائماً مشكلة: قد يكون فرعاً عادياً في الأتمتة.', 'Un fichier absent peut être une condition prévue.', 'A missing file may be an expected condition, not an exceptional crash.'], 'Test-Path notes.txt', 'Test-Path notes.txt', ['Test-Path']);
L8('p-reliability', ['فهم Error مقابل Boolean False', 'Différencier erreur et False', 'Separate an error from False'], ['Test-Path يعيد False عندما لا يجد العنصر؛ Get-Item على ملف غير موجود يسبب خطأ. التمييز مهم عند كتابة خطوات معالجة.', 'Test-Path rend False; Get-Item manquant provoque une erreur.', 'Test-Path returns False for a missing item, while Get-Item on the missing path can produce an error.'], ['ابدأ باختبار متوقع قبل استدعاء أمر يتطلب وجود الملف.', 'Testez l’existence avant une opération exigeante.', 'Check existence before executing an operation requiring a file.'], ['لا تخفِ كل الأخطاء بعمل catch فارغ في السكربت الحقيقي.', 'Ne masquez pas les erreurs avec un catch vide.', 'Avoid silently swallowing all errors in production scripts.'], 'Test-Path missing.txt', 'Test-Path missing.txt', ['Test-Path', 'Get-Item']);
L8('p-reliability', ['قراءة السجل قبل التصرف', 'Inspecter un journal avant d’agir', 'Inspect logs before taking action'], ['Select-String يبحث عن نص داخل محتوى قادم من pipeline. ابدأ بقراءة السجل لا بتغيير إعدادات الخدمة مباشرة.', 'Select-String filtre les lignes qui contiennent un motif donné.', 'Select-String filters lines matching a pattern. Inspect logs before changing configuration.'], ['الإخراج يشمل الأسطر التي تحوي ERROR فقط.', 'Le résultat conserve les lignes ERROR.', 'Only matching ERROR lines are returned.'], ['أي رسالة ERROR لا تعني تلقائياً أن النظام تعرض للاختراق.', 'Un événement ERROR ne signifie pas forcément une intrusion.', 'An ERROR record does not necessarily indicate a security incident.'], 'Get-Content logs/app.log | Select-String ERROR', 'Get-Content logs/app.log | Select-String ERROR', ['Select-String', 'Get-Content']);
L8('p-reliability', ['التحقق من JSON قبل تقرير', 'Valider JSON avant rapport', 'Validate JSON before reporting'], ['Test-Json يرجع True أو False على صيغة JSON. تحقق من الملف قبل تمريره إلى ConvertFrom-Json داخل خط معالجة.', 'Test-Json confirme la validité syntaxique avant conversion.', 'Test-Json checks basic JSON syntax before a later parsing step.'], ['مرر Get-Content إلى Test-Json بدلاً من التخمين من امتداد الملف.', 'Vérifiez le contenu, pas seulement le suffixe .json.', 'Validate content, not just the .json filename suffix.'], ['JSON صالح تركيبياً قد يحتوي مع ذلك على قيم خاطئة منطقياً.', 'Un JSON valide peut contenir des valeurs incorrectes.', 'Syntactically valid JSON can still contain semantically invalid data.'], 'Get-Content data/config.json | Test-Json', 'Get-Content data/config.json | Test-Json', ['Test-Json', 'Get-Content']);
L8('p-reliability', ['فصل التشخيص عن التغيير', 'Séparer diagnostic et modification', 'Separate diagnosis from changes'], ['قبل إصلاح عطل شبكة: اقرأ IP ثم route ثم DNS وأخيراً TCP. هذا التسلسل يقلل تغييرات غير ضرورية في Firewall.', 'Contrôlez IP, route, DNS et TCP avant de toucher au pare-feu.', 'Inspect IP, routing, DNS and TCP in order. Do not change firewall rules before identifying the failing layer.'], ['النتيجة تتغير حسب السيناريو الذي تختاره في مختبر v8.', 'Le résultat dépend du scénario de panne virtuelle.', 'Results change when you select different virtual fault scenarios.'], ['فتح كل المنافذ ليس علاجاً سليماً لفشل DNS أو Gateway.', 'Ouvrir tous les ports ne corrige pas DNS ou gateway.', 'Allowing all inbound traffic is not a safe fix for DNS or routing failures.'], 'Get-NetIPAddress; Get-NetRoute; Get-DnsClientServerAddress', 'Get-NetIPAddress; Get-NetRoute; Get-DnsClientServerAddress', ['Get-NetIPAddress', 'Get-NetRoute', 'Get-DnsClientServerAddress']);
