add("b-perms", LT(...["استعراض أسماء الملفات المخفية والسمات", "Examiner les noms cachés et les attributs", "Inspect hidden names and attributes"]), LT(...["أتقن استعراض أسماء الملفات المخفية والسمات عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer examiner les noms cachés et les attributs sur des exemples fictifs et vérifier le résultat.", "Practice inspect hidden names and attributes safely and verify the simulator's result."]), LT(...["يساعد عرض -a في عدم إغفال العناصر التي تبدأ بنقطة، و-l في قراءة الحقول المرتبطة بكل عنصر. ابدأ بالمعاينة قبل أي تعديل للصلاحيات.", "L’option -a inclut les fichiers cachés et -l montre les attributs. Inspectez toujours le contenu avant de modifier les droits.", "The -a option includes dotfiles and -l requests a detailed listing. Inventory the target before changing permissions."]), "ls -la DIR", "ls -la Documents", LT(...["يعرض الأمر محتويات Documents في وضع تعليمي؛ أسماء المالك والمجموعة والصلاحيات المعروضة هنا مبسطة.", "La commande inspecte Documents; les métadonnées du simulateur sont simplifiées.", "The command lists Documents, but simulator metadata is simplified and is not a real user or group database."]), LT(...["لا تعتبر عرض ls ضماناً بأن لك صلاحية القراءة أو الكتابة على نظام حقيقي.", "La présence dans ls ne garantit pas les permissions effectives.", "A filename in ls does not guarantee your real user can open or change it."]), "ls -la Documents", ["ls", "chmod"]);
add("b-perms", LT(...["قراءة الحجم والسمات قبل التحرير", "Examiner taille et attributs", "Inspect size and metadata before editing"]), LT(...["أتقن قراءة الحجم والسمات قبل التحرير عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer examiner taille et attributs sur des exemples fictifs et vérifier le résultat.", "Practice inspect size and metadata before editing safely and verify the simulator's result."]), LT(...["stat يعرض معلومات وصفية عن الملف مثل الحجم وبعض الطوابع الزمنية والصلاحيات. تستعمل هذه المعلومات لتوثيق الحالة قبل التغيير ومقارنتها بعده.", "stat affiche les métadonnées, notamment taille et horodatages. Elles servent à comparer l’état du fichier avant et après.", "stat exposes file metadata such as size and timestamps. Capture a baseline before editing so changes can be evaluated."]), "stat FILE", "stat notes.txt", LT(...["افحص notes.txt قبل استعمال cp أو chmod. بيانات الزمن والصلاحيات في المختبر ليست مأخوذة من قرصك.", "Examinez notes.txt avant cp ou chmod; ses données ne viennent pas du disque réel.", "Inspect notes.txt before cp or chmod. The displayed metadata is virtual."]), LT(...["لا تستنتج سلامة المحتوى من الحجم وحده؛ استعمل بصمة للمقارنة الدقيقة.", "Une taille identique ne garantit pas un contenu identique.", "Equal file sizes do not prove equal contents; compare hashes when that matters."]), "stat notes.txt", ["stat", "sha256sum"]);
add("b-perms", LT(...["نفّذ خطوة فقط عند وجود الملف", "Effectuer une action seulement si le fichier existe", "Run an action only when a file exists"]), LT(...["أتقن نفّذ خطوة فقط عند وجود الملف عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer effectuer une action seulement si le fichier existe sur des exemples fictifs et vérifier le résultat.", "Practice run an action only when a file exists safely and verify the simulator's result."]), LT(...["يربط && تنفيذ الأمر الثاني بنجاح الأول. test -f يتحقق من وجود ملف عادي؛ بهذه الطريقة لا تعتمد على رسالة خطأ متأخرة لمعرفة أن المدخل مفقود.", "&& lance la seconde commande uniquement si la première réussit. test -f vérifie qu’il s’agit d’un fichier ordinaire.", "The && operator runs the next command only after success. test -f confirms a regular file exists before moving on."]), "test -f FILE && echo OK", "test -f notes.txt && echo verified", LT(...["عندما يكون notes.txt موجوداً تظهر verified. عند غيابه لا ينفذ echo، وتبقى نتيجة الاختبار فاشلة.", "verified apparaît lorsque notes.txt existe; sinon echo n’est pas exécuté.", "The message appears when notes.txt exists; otherwise echo is skipped."]), LT(...["نجاح التحقق من وجود الملف لا يعني أن قراءته مسموحة.", "L’existence ne garantit pas la lecture.", "Existence does not imply read permission on a real filesystem."]), "test -f notes.txt && echo verified", ["test", "echo"]);
add("b-perms", LT(...["إنشاء نسخة ثم توثيق بصمتها", "Copier puis relever une empreinte", "Copy and record a digest"]), LT(...["أتقن إنشاء نسخة ثم توثيق بصمتها عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer copier puis relever une empreinte sur des exemples fictifs et vérifier le résultat.", "Practice copy and record a digest safely and verify the simulator's result."]), LT(...["في صيانة الأنظمة احتفظ بنسخة قبل التغيير، ثم احسب SHA-256 عليها. هذه الطريقة تفصل النسخة الاحتياطية عن الملف الأصلي وتسمح باختبار سلامة النسخ.", "Une copie préalable et son SHA-256 forment un point de comparaison reproductible avant modification.", "Copy first, then compute SHA-256 for the new file. The digest gives you a repeatable integrity check before making changes."]), "cp SRC DEST; sha256sum DEST", "cp notes.txt Documents/source-copy.txt; sha256sum Documents/source-copy.txt", LT(...["ينشئ cp نسخة في Documents ثم تحسب sha256sum قيمة النسخة. لإثبات تطابقها احسب أيضاً بصمة المصدر وقارن القيم.", "cp crée une copie dans Documents; sha256sum calcule son empreinte. Comparez-la à celle de la source.", "cp creates a separate file in Documents and sha256sum hashes it. Hash the source too to compare."]), LT(...["حساب بصمة النسخة وحدها لا يثبت أنها تطابق الأصل.", "Une seule empreinte ne prouve pas la correspondance à la source.", "A single hash of the copy cannot by itself verify the original was copied correctly."]), "cp notes.txt Documents/source-copy.txt; sha256sum Documents/source-copy.txt", ["cp", "sha256sum"]);
add("b-triage", LT(...["قراءة بداية سجل قبل البحث", "Lire le début d’un journal", "Inspect the beginning of a log"]), LT(...["أتقن قراءة بداية سجل قبل البحث عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer lire le début d’un journal sur des exemples fictifs et vérifier le résultat.", "Practice inspect the beginning of a log safely and verify the simulator's result."]), LT(...["ابدأ بالنظر إلى رأس الملف لفهم نوع السجلات وصيغ التوقيت وحقول الرسائل قبل بناء فلتر. head يعرض أول عدد محدد من الأسطر دون تعديل الملف.", "Lisez les premières lignes pour identifier la structure avant de créer des filtres. head n’altère pas le fichier.", "Read the start of a log to establish its format and fields before filtering. head is a non-destructive inspection command."]), "head -n N FILE", "head -n 2 logs/app.log", LT(...["-n 2 يحدد أول سطرين. غيّر العدد حسب طول المقدمة، ولا تعتبرهما عينة ممثلة لجميع الأحداث.", "-n 2 affiche les deux premières lignes; elles ne représentent pas forcément tout le journal.", "-n 2 selects the first two lines. They may not reflect later errors or trends."]), LT(...["قد يكون الخطأ في نهاية الملف؛ عندها استعمل tail أيضاً.", "Les erreurs récentes se trouvent souvent à la fin; utilisez aussi tail.", "Recent failures are often near the end; inspect with tail as well."]), "head -n 2 logs/app.log", ["head", "tail"]);
add("b-triage", LT(...["مراجعة أحدث الرسائل", "Lire les messages les plus récents", "Review the latest messages"]), LT(...["أتقن مراجعة أحدث الرسائل عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer lire les messages les plus récents sur des exemples fictifs et vérifier le résultat.", "Practice review the latest messages safely and verify the simulator's result."]), LT(...["tail مفيد خلال تشخيص حادثة لأنه يعرض نهاية السجل، لكن ترتيب الأحداث يعتمد على آلية الكتابة الفعلية. في نظام حقيقي قد توجد ملفات دوارة أو سجلات مركزية.", "tail lit la fin du fichier, utile pour les incidents récents, tout en tenant compte de la rotation des journaux.", "tail shows the end of a file, often useful for recent activity. Real logging systems may rotate files or aggregate multiple sources."]), "tail -n N FILE", "tail -n 2 logs/app.log", LT(...["يعرض آخر سطرين من سجل التدريب، مما يساعدك على ربط رسالة ERROR بما يليها.", "Les deux dernières lignes aident à relier ERROR aux messages suivants.", "The last two lines provide context around the error and its aftermath."]), LT(...["آخر سطر ليس دائماً آخر حادثة زمنياً إذا كان الملف مجمعاً من مصادر مختلفة.", "La dernière ligne n’est pas toujours le dernier événement chronologique.", "In merged logs, the last line may not be the newest event by timestamp."]), "tail -n 2 logs/app.log", ["tail", "head"]);
add("b-triage", LT(...["ربط الأخطاء بأرقام الأسطر", "Associer les erreurs aux numéros de ligne", "Attach line numbers to matching errors"]), LT(...["أتقن ربط الأخطاء بأرقام الأسطر عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer associer les erreurs aux numéros de ligne sur des exemples fictifs et vérifier le résultat.", "Practice attach line numbers to matching errors safely and verify the simulator's result."]), LT(...["الخيار -n يلحق رقم السطر بكل نتيجة حتى تستطيع الرجوع للمصدر وإضافة سياق قبل الحادثة وبعدها. حافظ على الملف الأصلي للتدقيق.", "Avec -n, chaque correspondance inclut son numéro de ligne afin de retrouver le contexte.", "The -n flag prefixes each match with a line number, making it easier to inspect surrounding context without rewriting the original log."]), "grep -n PATTERN FILE", "grep -n ERROR logs/app.log", LT(...["النتيجة 2:ERROR ... تعني أن المطابقة في السطر الثاني، ولا تعني أن الخطأ وقع مرتين.", "2:ERROR signifie ligne 2, pas deux erreurs.", "A prefix such as 2: means line two, not two failures."]), LT(...["أرقام الأسطر قد تتبدل بعد تدوير السجل أو تحديثه.", "Les numéros changent si le journal est modifié ou tourné.", "Line numbers change when logs are rotated or rewritten."]), "grep -n ERROR logs/app.log", ["grep"]);
add("b-triage", LT(...["فهم عداد أسطر Unix", "Comprendre le comptage des lignes Unix", "Understand Unix newline counts"]), LT(...["أتقن فهم عداد أسطر Unix عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer comprendre le comptage des lignes unix sur des exemples fictifs et vérifier le résultat.", "Practice understand unix newline counts safely and verify the simulator's result."]), LT(...["wc -l يحسب عدد محارف نهاية السطر (newline)، وليس بالضرورة عدد السطور المرئية في محرر النص. هذا فارق مهم إذا كان آخر سطر بلا newline.", "wc -l compte les caractères de fin de ligne; un dernier enregistrement sans retour final peut fausser l’intuition.", "wc -l counts newline delimiters. A file with an unterminated final line may show one more visual line than the count."]), "wc -l FILE", "wc -l logs/app.log", LT(...["إذا ظهرت نتيجة 2 رغم وجود ثلاثة أسطر ظاهرة، فهذا لأن السطر الأخير في بيانات المختبر لا ينتهي بمحرف newline.", "Le résultat 2 est possible avec trois lignes visibles si la dernière n’a pas de fin de ligne.", "A count of 2 for three displayed lines is possible because the final line has no trailing newline."]), LT(...["لا تستخدم wc -l وحده لعد السجلات إذا كان تنسيق الملف لا يضمن نهاية سطر.", "N’assimilez pas automatiquement un saut de ligne à un enregistrement.", "Do not assume every record is newline-terminated unless the format guarantees it."]), "wc -l logs/app.log", ["wc"]);
add("b-netops", LT(...["تصفية عناوين الواجهة", "Filtrer les adresses d’une interface", "Filter interface addresses"]), LT(...["أتقن تصفية عناوين الواجهة عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer filtrer les adresses d’une interface sur des exemples fictifs et vérifier le résultat.", "Practice filter interface addresses safely and verify the simulator's result."]), LT(...["اعرض عنوان الشبكة أولاً قبل اختبار DNS أو TCP. الجمع بين ip addr وgrep يوفر معاينة سريعة، لكن وجود IPv4 لا يضمن توفر البوابة أو الإنترنت.", "Affichez les adresses avec ip addr, puis filtrez-les. Une adresse valide ne prouve pas la connectivité.", "Inspect the interface address before higher-layer tests. An assigned IPv4 address alone does not prove the gateway or internet works."]), "ip addr | grep inet", "ip addr | grep inet", LT(...["يفصل Pipeline السطور التي تحتوي inet فقط من نتيجة ip addr الافتراضية.", "Le pipeline garde les lignes contenant inet dans la sortie fictive.", "The pipeline retains only lines containing inet from the simulated ip output."]), LT(...["قد تطابق كلمة inet أيضاً inet6؛ استعمل تعبيراً أدق لو احتجت IPv4 فقط.", "inet peut aussi correspondre à inet6; raffinez le filtre pour IPv4.", "The substring inet also matches inet6; narrow the pattern when you specifically need IPv4."]), "ip addr | grep inet", ["ip", "grep"]);
add("b-netops", LT(...["تحديد المسار الافتراضي", "Identifier la route par défaut", "Locate the default route"]), LT(...["أتقن تحديد المسار الافتراضي عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer identifier la route par défaut sur des exemples fictifs et vérifier le résultat.", "Practice locate the default route safely and verify the simulator's result."]), LT(...["المسار default يحدد وجهة حزم IP حين لا توجد قاعدة أكثر تحديداً. قبل اتهام DNS بفشل الشبكة، افحص بوابة الخروج والمسار الافتراضي.", "La route default fournit le prochain saut pour les destinations non couvertes par une route plus précise.", "The default route gives a next hop for destinations not covered by a more specific route. Check it before assuming every failure is DNS."]), "ip route | grep default", "ip route | grep default", LT(...["سيظهر المسار عبر 192.0.2.1 في الحالة الافتراضية السليمة.", "Le modèle sain montre le prochain saut 192.0.2.1.", "The healthy synthetic network shows a route via 192.0.2.1."]), LT(...["وجود default لا يضمن أن البوابة تستجيب؛ جرّب اختبار الوصول إليها.", "Une route présente ne garantit pas une passerelle opérationnelle.", "A listed default route does not guarantee the gateway is reachable."]), "ip route | grep default", ["ip", "grep"]);
add("b-netops", LT(...["فهم الفرق بين الاسم والوصول", "Distinguer résolution et connectivité", "Separate DNS resolution from reachability"]), LT(...["أتقن فهم الفرق بين الاسم والوصول عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer distinguer résolution et connectivité sur des exemples fictifs et vérifier le résultat.", "Practice separate dns resolution from reachability safely and verify the simulator's result."]), LT(...["عند استعمال اسم مضيف يمر اختبار الاتصال عادة بمرحلة حل الاسم ثم إرسال ICMP. فشل ping قد يكون بسبب DNS أو الشبكة أو حظر ICMP؛ لا تستنتج السبب من اختبار واحد.", "ping avec un nom dépend d’abord du DNS, puis d’ICMP. Son échec a plusieurs causes possibles.", "Pinging a hostname involves name resolution followed by ICMP. Failure can come from DNS, routing, or blocked ICMP, so corroborate with other probes."]), "ping -c N HOST", "ping -c 1 training.lab", LT(...["المختبر يعيد نموذج استجابة ثابتاً؛ -c 1 لا يغيّر عدد الحزم المذكور في الرسالة الاصطناعية.", "Le labo utilise une réponse fixe; -c 1 ne change pas le texte du nombre de paquets.", "The simulator uses fixed response text; its packet-count display does not adapt to -c 1."]), LT(...["لا تفسر أرقام الحزم الاصطناعية كمقاييس أداء أو اتصال حقيقي.", "Les statistiques fictives ne mesurent pas le réseau réel.", "Synthetic packet statistics are not real network latency or reliability metrics."]), "ping -c 1 training.lab", ["ping"]);
add("b-netops", LT(...["قراءة بداية استجابة HTTP", "Lire les premiers en-têtes HTTP", "Read the beginning of an HTTP response"]), LT(...["أتقن قراءة بداية استجابة HTTP عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer lire les premiers en-têtes http sur des exemples fictifs et vérifier le résultat.", "Practice read the beginning of an http response safely and verify the simulator's result."]), LT(...["يفصل curl -I ترويسات الاستجابة دون تنزيل الجسم في الاستخدام الحقيقي، ثم يعرض head أول الأسطر. يساعد هذا في تحديد رمز الحالة والخادم بعد التحقق من DNS وTCP.", "curl -I examine les en-têtes; head limite la sortie pour lire le code HTTP et le serveur.", "curl -I requests headers on a real system; head limits the display so you can quickly inspect the HTTP status and server identity after DNS/TCP checks."]), "curl -I URL | head -n N", "curl -I https://training.lab | head -n 2", LT(...["النتيجة HTTP/1.1 200 OK اصطناعية ولا تتصل بالموقع الحقيقي.", "Le statut 200 du laboratoire est simulé, sans requête réseau réelle.", "The 200 status here is synthetic; no real request or TLS handshake occurs."]), LT(...["نجاح HTTP لا يؤكد أن التطبيق يقدم البيانات الصحيحة؛ يحتاج فحصاً إضافياً.", "HTTP 200 ne garantit pas que le contenu métier est correct.", "HTTP 200 does not guarantee that an application serves correct data."]), "curl -I https://training.lab | head -n 2", ["curl", "head"]);
add("b-reliable", LT(...["مراجعة مخرجات Pipeline قبل الاعتماد عليها", "Vérifier la sortie d’un pipeline", "Verify pipeline output before relying on it"]), LT(...["أتقن مراجعة مخرجات Pipeline قبل الاعتماد عليها عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer vérifier la sortie d’un pipeline sur des exemples fictifs et vérifier le résultat.", "Practice verify pipeline output before relying on it safely and verify the simulator's result."]), LT(...["الـPipeline يمرر stdout من الأمر الأول إلى الثاني، وقد تختلف طريقة احتساب نهاية السطر حسب الأمر والمحاكي. احسب المدخل الفعلي ولا تفترض أنه سلسلة بطول ثابت.", "Un pipeline transmet stdout. Les fins de ligne changent selon les outils et la simulation.", "A pipeline connects stdout to the next command. Counting bytes requires understanding exact newline behavior and the data passed through."]), "echo TEXT | wc -c", "echo test | wc -c", LT(...["النتيجة 4 في محاكي الموقع لأن echo الافتراضي لا يضيف newline لهذا الحساب؛ في Bash الحقيقي يمكن أن تكون 5.", "Le simulateur donne 4 ici; un echo réel ajoute normalement un saut de ligne, d’où 5.", "The simulator reports 4 because its echo output lacks a counted newline; real echo normally yields 5."]), LT(...["لا تنسخ نتائج العد من المحاكاة إلى تقرير إنتاجي دون اختبارها في النظام الحقيقي.", "Ne reprenez pas ce comptage fictif dans un rapport de production.", "Validate exact byte counts on the real toolchain before using them in production."]), "echo test | wc -c", ["echo", "wc"]);
add("b-reliable", LT(...["كتابة أسطر محددة مع printf", "Construire des lignes avec printf", "Create explicit lines with printf"]), LT(...["أتقن كتابة أسطر محددة مع printf عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer construire des lignes avec printf sur des exemples fictifs et vérifier le résultat.", "Practice create explicit lines with printf safely and verify the simulator's result."]), LT(...["printf يعطي تحكماً أدق بتسلسل newline مقارنة بالاعتماد على سلوك echo. تحديد نهاية السطر يجعل عد السجلات وعمليات المعالجة أكثر توقعاً.", "printf permet de contrôler les retours à la ligne explicitement, ce qui rend le comptage plus prévisible.", "printf lets you explicitly write newline delimiters, making record counting and data exchange more predictable than relying on echo defaults."]), "printf \"A\\nB\\n\" | wc -l", "printf \"first\\nsecond\\n\" | wc -l", LT(...["يولد السطران first وsecond وينتهي كل منهما بـ\\n، لذلك يتعرف wc -l على سطرين.", "Les deux enregistrements se terminent par \\n et wc -l compte deux lignes.", "Both entries end with an explicit newline escape, so wc -l counts two lines."]), LT(...["استعمل علامات اقتباس صحيحة حتى لا يفسر Shell محارف النمط قبل printf.", "Protégez le format avec des guillemets adaptés.", "Quote the format string so the shell does not reinterpret special characters unexpectedly."]), "printf \"first\\nsecond\\n\" | wc -l", ["printf", "wc"]);
add("b-reliable", LT(...["التحقق من النتيجة بعد الإنشاء", "Vérifier après création", "Verify after creating directories"]), LT(...["أتقن التحقق من النتيجة بعد الإنشاء عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer vérifier après création sur des exemples fictifs et vérifier le résultat.", "Practice verify after creating directories safely and verify the simulator's result."]), LT(...["بعد إنشاء المجلد راجع النتيجة بدلاً من افتراض أن العملية نجحت. -p ينشئ الآباء الناقصين لكنه لا يثبت أن المجلد الجديد فارغ أو أن الصلاحيات مناسبة.", "Après mkdir -p, listez le dossier pour confirmer le résultat. -p ne prouve pas que la cible est vide ou accessible.", "After mkdir -p, inspect the parent directory. Creating missing parents does not imply the target is empty or has appropriate permissions."]), "mkdir -p PATH; ls PARENT", "mkdir -p training/archive; ls training", LT(...["ينشئ الأمر training/archive ثم يعرضه ضمن محتويات training.", "La commande crée training/archive puis affiche son nom dans training.", "The command creates training/archive and lists the resulting folder under training."]), LT(...["استخدم && بدل ; عندما يجب ألا ينفذ التحقق إلا بعد نجاح الإنشاء.", "Préférez && à ; lorsque la seconde étape dépend du succès de la première.", "Prefer && instead of ; when the verification command must run only if creation succeeds."]), "mkdir -p training/archive; ls training", ["mkdir", "ls"]);
add("b-reliable", LT(...["معالجة الفشل بالبديل المنطقي", "Prévoir une solution de secours", "Handle failures with a fallback"]), LT(...["أتقن معالجة الفشل بالبديل المنطقي عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer prévoir une solution de secours sur des exemples fictifs et vérifier le résultat.", "Practice handle failures with a fallback safely and verify the simulator's result."]), LT(...["العامل || يشغّل الفرع التالي عندما يفشل الأمر السابق برمز خروج غير صفري. هذه طريقة قصيرة لمعالجة فشل متوقع، لا لإخفاء كل الأخطاء.", "|| exécute une commande de secours si la précédente échoue. Il ne faut pas masquer systématiquement les incidents.", "The || operator triggers a fallback on nonzero exit status. Use it for expected failures, not to silently mask unexpected system errors."]), "COMMAND || FALLBACK", "cat missing.txt || echo fallback", LT(...["لأن missing.txt غير موجود سيظهر خطأ القراءة، ثم تُعرض fallback.", "Comme le fichier manque, l’erreur apparaît, puis le texte fallback.", "Because the file is missing, the simulator shows a read error followed by fallback."]), LT(...["وجود رسالة خطأ قبل النص البديل لا يعني أن الفرع الثاني لم يعمل.", "Une erreur affichée n’empêche pas forcément le traitement de secours.", "Seeing an error message does not mean the fallback branch was skipped."]), "cat missing.txt || echo fallback", ["cat", "echo"]);
add("p-adminops", LT(...["أخذ عينة من الخدمات قبل التصفية", "Échantillonner les services avant filtrage", "Sample service records before filtering"]), LT(...["أتقن أخذ عينة من الخدمات قبل التصفية عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer échantillonner les services avant filtrage sur des exemples fictifs et vérifier le résultat.", "Practice sample service records before filtering safely and verify the simulator's result."]), LT(...["قبل وضع شروط معقدة افهم شكل الكائنات التي يعيدها Get-Service. Select-Object -First يعرض عينة صغيرة تسهّل معرفة الأعمدة والتأكد من وجود البيانات.", "Inspectez les objets de Get-Service sur un petit échantillon avant toute logique de filtrage.", "Inspect a small sample of Get-Service objects before writing elaborate filters. The first records reveal what properties are available."]), "Get-Service | Select-Object -First N", "Get-Service | Select-Object -First 3", LT(...["يعرض ثلاثة عناصر من قائمة الخدمات الافتراضية، وليس خدمات جهاز Windows.", "Les trois services affichés sont fictifs, pas ceux de votre Windows.", "The first three listed services are synthetic, not from your Windows installation."]), LT(...["اختيار أول ثلاثة عناصر لا يعني أنها الأهم أو الأكثر عرضة للمشاكل.", "Les premiers éléments ne sont pas forcément les plus importants.", "The first three records are not necessarily the most important ones."]), "Get-Service | Select-Object -First 3", ["Get-Service", "Select-Object"]);
add("p-adminops", LT(...["ترتيب العمليات حسب استهلاك CPU", "Trier les processus selon le CPU", "Rank processes by CPU usage"]), LT(...["أتقن ترتيب العمليات حسب استهلاك CPU عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer trier les processus selon le cpu sur des exemples fictifs et vérifier le résultat.", "Practice rank processes by cpu usage safely and verify the simulator's result."]), LT(...["يمكن ترتيب كائنات العمليات حسب خاصية CPU قبل عرض أعلى النتائج. في PowerShell الحقيقي تُقاس CPU غالباً بزمن المعالج المتراكم، وليس بنسبة الاستخدام اللحظي.", "Triez les objets par CPU, mais gardez en tête que cette propriété est généralement un temps cumulé et non un pourcentage instantané.", "Sort process objects by CPU. In real PowerShell, CPU often represents accumulated processor time rather than instantaneous percentage load."]), "Get-Process | Sort-Object CPU -Descending | Select-Object -First N", "Get-Process | Sort-Object -Property CPU -Descending | Select-Object -First 3", LT(...["يعرض الأمر ثلاث عمليات وهمية بعد الترتيب تنازلياً حسب الخاصية.", "La commande retourne trois processus simulés triés dans l’ordre décroissant.", "The command returns three simulated processes sorted by CPU descending."]), LT(...["لا تستخدم CPU المتراكم وحده لتحديد سبب بطء الجهاز؛ راقب الذاكرة والزمن أيضاً.", "Le CPU cumulé seul ne suffit pas à diagnostiquer une machine lente.", "Cumulative CPU alone cannot identify the cause of a current slowdown."]), "Get-Process | Sort-Object -Property CPU -Descending | Select-Object -First 3", ["Get-Process", "Sort-Object", "Select-Object"]);
add("p-adminops", LT(...["إحصاء الخدمات حسب الحالة", "Compter les services par état", "Count services grouped by status"]), LT(...["أتقن إحصاء الخدمات حسب الحالة عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer compter les services par état sur des exemples fictifs et vérifier le résultat.", "Practice count services grouped by status safely and verify the simulator's result."]), LT(...["Group-Object يحوّل سجلات الخدمات إلى مجموعات حسب Status؛ ثم يمكنك اختيار Count وName لإنتاج تقرير صغير بدل قراءة جدول كبير.", "Group-Object regroupe les services par Status. Select-Object en extrait Count et Name.", "Group-Object clusters services by Status. Select-Object then projects the counts and group names into a compact report."]), "Get-Service | Group-Object Status | Select-Object Count,Name", "Get-Service | Group-Object Status | Select-Object Count,Name", LT(...["ستظهر مجموعة Running وأخرى Stopped من بيانات المختبر، بأعداد قابلة للمقارنة.", "Vous verrez Running et Stopped avec leurs effectifs virtuels.", "The simulator reports groups such as Running and Stopped with synthetic counts."]), LT(...["عدد الخدمات المتوقفة ليس بالضرورة مؤشراً على عطل؛ بعضها يعمل عند الطلب فقط.", "Un service arrêté n’est pas nécessairement en panne.", "Stopped services are not automatically faulty; many are demand-start services."]), "Get-Service | Group-Object Status | Select-Object Count,Name", ["Get-Service", "Group-Object", "Select-Object"]);
add("p-adminops", LT(...["إظهار الخصائص المهمة فقط", "Afficher seulement les propriétés utiles", "Project only useful properties"]), LT(...["أتقن إظهار الخصائص المهمة فقط عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer afficher seulement les propriétés utiles sur des exemples fictifs et vérifier le résultat.", "Practice project only useful properties safely and verify the simulator's result."]), LT(...["بدلاً من قراءة كل خصائص الخدمة، استعمل Select-Object لإبراز Name وStatus عند التشخيص الأولي. هذا يغيّر طريقة العرض ولا يغيّر حالة أي خدمة.", "Select-Object conserve Name et Status pour un premier diagnostic sans changer les services.", "Select-Object projects Name and Status for an initial status review. It does not start, stop or reconfigure any service."]), "Get-Service | Select-Object Status,Name", "Get-Service | Select-Object -Property Status,Name", LT(...["يعرض عمود الحالة إلى جانب اسم كل خدمة وهمية.", "La sortie montre le statut et le nom de chaque service fictif.", "The output displays status and name for each synthetic service."]), LT(...["استخدام Format-Table داخل Pipeline مبكراً قد يجعل معالجة الكائنات لاحقاً أصعب.", "Évitez de formater trop tôt si vous voulez encore traiter les objets.", "Avoid formatting too early if later pipeline stages need the original objects."]), "Get-Service | Select-Object -Property Status,Name", ["Get-Service", "Select-Object"]);
add("p-netops", LT(...["التحقق من حالة المحول أولاً", "Vérifier d’abord l’adaptateur", "Check adapter status first"]), LT(...["أتقن التحقق من حالة المحول أولاً عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer vérifier d’abord l’adaptateur sur des exemples fictifs et vérifier le résultat.", "Practice check adapter status first safely and verify the simulator's result."]), LT(...["حالة المحول هي الطبقة الأولى في تشخيص فقدان الشبكة. لا تبدأ بفحص خدمة الويب قبل التأكد من أن واجهة Ethernet أو Wi-Fi نشطة فعلاً.", "Commencez le diagnostic au niveau de l’adaptateur avant de vérifier DNS ou les services.", "Start at the adapter layer before troubleshooting DNS, routing or remote services. A disabled adapter can explain multiple higher-layer failures."]), "Get-NetAdapter | Select-Object Name,Status", "Get-NetAdapter | Select-Object Name,Status", LT(...["يعرض المختبر Ethernet مع حالة Up أو Disabled بحسب السيناريو.", "Ethernet est indiqué Up ou Disabled selon le scénario fictif.", "The simulator shows Ethernet as Up or Disabled according to the selected synthetic incident."]), LT(...["الحالة Up لا تعني اتصالاً حقيقياً بالإنترنت أو نجاح الوصول إلى DNS.", "Up ne garantit pas un accès à Internet ou au DNS.", "An Up adapter status does not prove DNS or internet connectivity."]), "Get-NetAdapter | Select-Object Name,Status", ["Get-NetAdapter", "Select-Object"]);
add("p-netops", LT(...["الربط بين عنوان IP والواجهة", "Associer IP et interface", "Map IP addresses to interfaces"]), LT(...["أتقن الربط بين عنوان IP والواجهة عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer associer ip et interface sur des exemples fictifs et vérifier le résultat.", "Practice map ip addresses to interfaces safely and verify the simulator's result."]), LT(...["لا يكفي تسجيل عنوان IP وحده في التقرير. اربطه باسم الواجهة لتمييز الاتصالات المتعددة والمحولات الافتراضية.", "Reliez chaque adresse IP à InterfaceAlias pour distinguer plusieurs cartes et interfaces virtuelles.", "When recording an IP address, preserve InterfaceAlias so you can distinguish multiple adapters and virtual interfaces."]), "Get-NetIPAddress | Select-Object IPAddress,InterfaceAlias", "Get-NetIPAddress | Select-Object IPAddress,InterfaceAlias", LT(...["يرجع العرض عنوان 192.0.2.10 المرتبط بالواجهة Ethernet الوهمية.", "La sortie associe 192.0.2.10 à l’interface fictive Ethernet.", "The projected object links 192.0.2.10 to the synthetic Ethernet interface."]), LT(...["العنوان 192.0.2.10 مخصص للتوثيق والمحاكاة؛ لا تعتبره عنوان جهازك.", "192.0.2.10 est réservé aux exemples; ce n’est pas votre adresse.", "192.0.2.10 is a documentation address, not the address of your device."]), "Get-NetIPAddress | Select-Object IPAddress,InterfaceAlias", ["Get-NetIPAddress", "Select-Object"]);
add("p-netops", LT(...["قراءة وجهة المسار والبوابة معاً", "Lire destination et passerelle", "Read route destination and next hop"]), LT(...["أتقن قراءة وجهة المسار والبوابة معاً عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer lire destination et passerelle sur des exemples fictifs et vérifier le résultat.", "Practice read route destination and next hop safely and verify the simulator's result."]), LT(...["المسار يطابق DestinationPrefix ويحدد NextHop، لذلك لا تقرأ عنوان البوابة منفصلاً عن وجهة التوجيه. قاعدة أكثر تحديداً قد تتغلب على المسار الافتراضي.", "Associez DestinationPrefix à NextHop; une route plus spécifique prime souvent sur la route par défaut.", "Read DestinationPrefix alongside NextHop. A more-specific route can override the default route, so the gateway must be interpreted in context."]), "Get-NetRoute | Select-Object DestinationPrefix,NextHop", "Get-NetRoute | Select-Object DestinationPrefix,NextHop", LT(...["تُظهر البيانات الافتراضية 0.0.0.0/0 و192.0.2.1 كمسار عام.", "La table simulée contient 0.0.0.0/0 via 192.0.2.1.", "The synthetic table includes a default route 0.0.0.0/0 via 192.0.2.1."]), LT(...["وجود البوابة في الجدول لا يؤكد وصول الحزم إليها.", "Une passerelle affichée ne garantit pas qu’elle réponde.", "A listed next hop does not prove packets can reach it."]), "Get-NetRoute | Select-Object DestinationPrefix,NextHop", ["Get-NetRoute", "Select-Object"]);
add("p-netops", LT(...["التحقق من منفذ TCP برهاناً منفصلاً", "Tester un port TCP séparément", "Test TCP reachability separately"]), LT(...["أتقن التحقق من منفذ TCP برهاناً منفصلاً عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer tester un port tcp séparément sur des exemples fictifs et vérifier le résultat.", "Practice test tcp reachability separately safely and verify the simulator's result."]), LT(...["قد ينجح DNS وICMP بينما يفشل TCP بسبب الخدمة أو الجدار الناري. Test-NetConnection -Port يعرض نتيجة الاتصال بالمنفذ ضمن كائن غني بالمعلومات.", "DNS et ICMP peuvent réussir alors que TCP échoue. Test-NetConnection -Port indique ce résultat indépendamment.", "DNS and ICMP may work while TCP fails because of the service or firewall. Test-NetConnection -Port checks the target port separately."]), "Test-NetConnection HOST -Port PORT | Select-Object ComputerName,TcpTestSucceeded", "Test-NetConnection training.lab -Port 443 | Select-Object ComputerName,TcpTestSucceeded", LT(...["اقرأ TcpTestSucceeded في النتيجة: True تعني نجاح الاتصال الافتراضي فقط.", "Lisez TcpTestSucceeded; True ne concerne que la connexion simulée.", "Read TcpTestSucceeded; True refers only to the virtual network model."]), LT(...["نجاح اتصال TCP لا يعني أن محتوى HTTPS صالح أو أن TLS تم التحقق منه.", "TCP réussi ne prouve ni validité TLS ni contenu HTTP correct.", "Successful TCP reachability does not prove TLS validity or correct HTTP responses."]), "Test-NetConnection training.lab -Port 443 | Select-Object ComputerName,TcpTestSucceeded", ["Test-NetConnection", "Select-Object"]);
