add("p-reliability", LT(...["ابدأ بالدليل قبل تخمين السبب", "Chercher des preuves avant de conclure", "Collect evidence before guessing a cause"]), LT(...["أتقن ابدأ بالدليل قبل تخمين السبب عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer chercher des preuves avant de conclure sur des exemples fictifs et vérifier le résultat.", "Practice collect evidence before guessing a cause safely and verify the simulator's result."]), LT(...["إذا فشل التطبيق فلا تخمن أن المشكلة DNS مباشرة. عرض NextHop خطوة صغيرة لفحص طبقة التوجيه، ثم تحتاج اختبار وصول مستقل قبل إصدار حكم.", "En cas d’échec applicatif, inspectez NextHop puis testez la connectivité avant d’accuser le DNS.", "When an app fails, inspect the default next hop as one piece of evidence. Confirm gateway reachability independently before blaming DNS."]), "Get-NetRoute | Select-Object NextHop", "Get-NetRoute | Select-Object NextHop", LT(...["سترى 192.0.2.1 ضمن حالة المختبر؛ هذا لا يثبت نجاح الوصول إليه.", "192.0.2.1 apparaît, mais ce n’est pas un test d’accessibilité.", "The synthetic next hop appears as 192.0.2.1; that alone is not a reachability test."]), LT(...["لا تخلط بين حالة إعداد مسار في الجدول ونتيجة اتصال حقيقية.", "Une route configurée et une connexion réussie sont deux choses différentes.", "A configured route and a successful connection are different facts."]), "Get-NetRoute | Select-Object NextHop", ["Get-NetRoute", "Select-Object"]);
add("p-reliability", LT(...["اختبار مجلد قبل الاعتماد عليه", "Vérifier un dossier avant utilisation", "Check a working folder before using it"]), LT(...["أتقن اختبار مجلد قبل الاعتماد عليه عبر مثال آمن، ثم قارن النتيجة بالشرح والملاحظات.", "Pratiquer vérifier un dossier avant utilisation sur des exemples fictifs et vérifier le résultat.", "Practice check a working folder before using it safely and verify the simulator's result."]), LT(...["قبل كتابة تقرير داخل مجلد اختبر وجود المسار بدلاً من اكتشاف عدم وجوده بعد عدة خطوات. Test-Path يعطي Boolean ولا يخبرك وحده بنوع العنصر.", "Test-Path vérifie l’existence d’un chemin avant les opérations dépendantes; il ne précise pas toujours le type.", "Before writing to a directory, verify the path exists. Test-Path returns a Boolean and does not by itself tell you its item type."]), "Test-Path PATH", "Test-Path logs", LT(...["يرجع True لأن logs ضمن المجلدات التي بدأت بها بيئة المختبر.", "Le résultat est True car logs fait partie des dossiers initiaux.", "The result is True because logs is part of the seeded sandbox directory tree."]), LT(...["True لا يضمن حق الكتابة داخل المجلد في نظام Windows الحقيقي.", "True ne garantit pas les droits d’écriture.", "True does not guarantee write permissions on a real Windows directory."]), "Test-Path logs", ["Test-Path"]);
